3	import { createReducerAndAtoms } from "@/utils/createReducer";
4	import type { DatasetsState } from "./types";
5	import { atom, useAtomValue } from "jotai";
6	import type { VariableName } from "../variables/types";
7	import type {
8	  DataColumnPreview,
9	  OperationMessageData,
10	} from "../kernel/messages";
11	import { previewDatasetColumn } from "../network/requests";
12	
13	function initialState(): DatasetsState {
14	  return {
15	    tables: [],
16	    expandedTables: new Set(),
17	    expandedColumns: new Set(),
18	    columnsPreviews: new Map(),
19	  };
20	}
21	
22	const {
23	  reducer,
24	  createActions,
25	  valueAtom: datasetsAtom,
26	  useActions,
27	} = createReducerAndAtoms(initialState, {
28	  addDatasets: (state, datasets: OperationMessageData<"datasets">) => {
29	    // Quietly in the background make requests to get the previews for
30	    // opened columns, in the new tables
31	    for (const table of datasets.tables) {
32	      for (const column of table.columns) {
33	        const tableColumn = `${table.name}:${column.name}` as const;
34	        if (state.expandedColumns.has(tableColumn)) {
35	          // Fire and forget
36	          void previewDatasetColumn({
37	            tableName: table.name,
38	            columnName: column.name,
39	            source: table.source,
40	            sourceType: table.source_type,
41	          });
42	        }
43	      }
44	    }
45	
46	    // Prev tables
47	    let prevTables = state.tables;
48	    if (datasets.clear_channel) {
49	      prevTables = prevTables.filter((table) => {
50	        return table.source !== datasets.clear_channel;
51	      });
52	    }
53	
54	    // Put new tables at the top
55	    const newTables = [...datasets.tables, ...prevTables];
56	
57	    // Dedupe by name and source
58	    const seen = new Set();
59	    const dedupedTables = newTables.filter((table) => {
60	      const key = `${table.name}:${table.source}`;
61	      if (seen.has(key)) {
62	        return false;
63	      }
64	      seen.add(key);
65	      return true;
66	    });
67	
68	    const sortedTables = dedupedTables.sort((a, b) => {
69	      return a.name.localeCompare(b.name);
70	    });
71	
72	    return {
73	      ...state,
74	      tables: sortedTables,
75	    };
76	  },
77	  filterDatasetsFromVariables: (state, variableNames: VariableName[]) => {
78	    const names = new Set(variableNames);
79	    // Filter out tables that come from variables that are not in the list
80	    const tables = state.tables.filter((table) => {
81	      // If there's no variable name, it's not a variable and we should keep it
82	      if (!table.variable_name) {
83	        return true;
84	      }
85	      return names.has(table.variable_name as VariableName);
86	    });
87	    return { ...state, tables };
88	  },
89	  toggleTable: (state, tableName: string) => {
90	    const expandedTables = new Set(state.expandedTables);
91	    if (expandedTables.has(tableName)) {
92	      expandedTables.delete(tableName);
93	    } else {
94	      expandedTables.add(tableName);
95	    }
96	    return { ...state, expandedTables };
97	  },
98	  toggleColumn: (state, opts: { table: string; column: string }) => {
99	    const tableColumn = `${opts.table}:${opts.column}` as const;
100	    const expandedColumns = new Set(state.expandedColumns);
101	    if (expandedColumns.has(tableColumn)) {
102	      expandedColumns.delete(tableColumn);
103	    } else {
104	      expandedColumns.add(tableColumn);
105	    }
106	    return { ...state, expandedColumns };
107	  },
108	  closeAllColumns: (state) => {
109	    return { ...state, expandedColumns: new Set() };
110	  },
111	  addColumnPreview: (state, preview: DataColumnPreview) => {
112	    const tableColumn = `${preview.table_name}:${preview.column_name}` as const;
113	    const columnsPreviews = new Map(state.columnsPreviews);
114	    columnsPreviews.set(tableColumn, preview);
115	    return { ...state, columnsPreviews };
116	  },
117	});
118	
119	/**
120	 * React hook to get the datasets state.
121	 */
122	export const useDatasets = () => useAtomValue(datasetsAtom);
123	
124	export const datasetTablesAtom = atom((get) => get(datasetsAtom).tables);
125	
126	export const expandedColumnsAtom = atom(new Set<string>());
127	export const closeAllColumnsAtom = atom(false);
128	
129	/**
130	 * React hook to get the datasets actions.
131	 */
132	export function useDatasetsActions() {
133	  return useActions();
134	}
135	
136	export { datasetsAtom };
137	
138	export const exportedForTesting = {
139	  reducer,
140	  createActions,
141	  initialState,
142	};
