 * Define a Python interpolation parser for Markdown.
 *
 * This enables template-style curly brace interpolation blocks (e.g.
 * `{variable}`) inside Markdown to be parsed and highlighted as Python.
 *
 * @param pythonParser CodeMirror {@link Parser} for Python
 * @param isActivated whether the interpolation parsing is currently enabled
 * @returns Markdown extension
 */
export function parsePython(
  pythonParser: Parser,
  isActivated: () => boolean,
): MarkdownConfig {
  const defineNodes: NodeSpec[] = [
    { name: PYTHON, style: tags.emphasis },
    { name: PYTHON_MARK, style: tags.processingInstruction },
  ];

  return {
    defineNodes,
    parseInline: [
      {
        name: PYTHON,
        parse(cx: InlineContext, next: number, pos: number): number {
          // Only parse when the interpolation feature is active.
          if (!isActivated()) {
            return -1;
          }

          const isOpen = next === CHAR_CODES.OPEN_BRACE;
          const isClose = next === CHAR_CODES.CLOSE_BRACE;

          // Not a curly brace, nothing to do.
          if (!isOpen && !isClose) {
            return -1;
