              return -1;
            }
          }

          // Similarly ignore escaped double close braces (e.g. `}}`).
          if (isClose) {
            if (
              cx.char(pos + 1) === CHAR_CODES.CLOSE_BRACE ||
              cx.char(pos - 1) === CHAR_CODES.CLOSE_BRACE
            ) {
              return -1;
            }
          }

          return cx.addDelimiter(
            PYTHON_DELIMITER,
            pos,
            pos + 1,
            isOpen,
            isClose,
          );
        },
      },
    ],
    wrap: parseMixed((node) => {
      if (node.type.name === PYTHON) {
        // Remove the surrounding braces from the Python parser overlay,
        // otherwise they won't be highlighted.
        const from = node.from + 1;
        const to = node.to - 1;

        // Ensure valid ranges
        if (from >= to || from < 0 || to < 0) {
          return null;
        }

        return {
          parser: pythonParser,
          overlay: [{ from, to }],
        };
      }

      return null;
    }),
  };
