/**
 * Build the list of completions from the current global variables state.
 */
function getVariableCompletions(): Completion[] {
  const variables = store.get(variablesAtom);
  return Object.values(variables).map(
    (variable): Completion => ({
      label: variable.name,
      displayLabel: variable.name,
      type: "variable",
      detail: variable.dataType ?? undefined,
      boost: 10,
    }),
  );
}

/**
 * Autocomplete extension for variable names inside embedded Python
 * interpolation blocks.
 *
 * The completions are provided through the Python language data facet so they
 * are only offered while the cursor is inside the embedded Python overlay.
 *
 * @param isActivated whether the interpolation completions are enabled
 */
export function embeddedPythonCompletions(
  isActivated: () => boolean,
): Extension {
  return [
    pythonLanguage.data.of({
      autocomplete: (context: CompletionContext): CompletionResult | null => {
        if (!isActivated()) {
          return null;
        }

        if (!context.explicit) {
          return null;
        }

        const word = context.matchBefore(/\w*/);
        if (!word) {
          return null;
        }

        return {
          from: word.from,
          options: getVariableCompletions(),
          validFor: /^\w*$/,
        };
      },
    }),
  ];
}

/**
 * Completion source for variable names inside a single-brace interpolation
 * block (e.g. `{var}`).
 *
 * Returns null when the cursor is not inside a valid single-brace block:
 * - there is no open brace before the cursor,
 * - the block has already been closed (a closing brace appears after the last
 *   open brace),
 * - the open brace is part of a double-brace escape sequence (e.g. `{{`).
 */
export function variableCompletionSource(
  context: CompletionContext,
): CompletionResult | null {
  const textBefore = context.state.sliceDoc(0, context.pos);

  // Must have an open brace before the cursor.
  const lastOpenBrace = textBefore.lastIndexOf("{");
  if (lastOpenBrace === -1) {
    return null;
  }

  // If a closing brace appears after the last open brace, the block is already
  // closed and we are outside of it.
  const lastCloseBrace = textBefore.lastIndexOf("}");
  if (lastCloseBrace > lastOpenBrace) {
    return null;
  }

  // Ignore double-brace escape sequences (e.g. `{{`).
  if (
    textBefore.charAt(lastOpenBrace + 1) === "{" ||
    textBefore.charAt(lastOpenBrace - 1) === "{"
  ) {
    return null;
  }

  const word = context.matchBefore(/\w*/);
  if (!word) {
    return null;
  }

  return {
    from: word.from,
    options: getVariableCompletions(),
    validFor: /^\w*$/,
  };
}
